const masukan: unknown[] = ["kopi", 3, true, "teh"];
for (const x of masukan) {
  if (typeof x === "string") {
    console.log("Teks:", x.toUpperCase());
  } else if (typeof x === "number") {
    console.log("Angka:", x * 10);
  }
}
console.log("Selesai", masukan.length);

