cards.solution:
const data: unknown[] = ["gula", 20, true, "kopi", 25];
let jumlah = 0;
const teks: string[] = [];
for (const x of data) {
  if (typeof x === "number") {
    jumlah += x;
  } else if (typeof x === "string") {
    teks.push(x);
  }
}
console.log("Jumlah:", jumlah);
console.log("Teks:", teks.join(","));
